function beginSteps(){stepIndex=0;logEvent('textbook_return',{payload:{sourceRef:current.remediation.sourceRef,attemptNo:attemptNo()}});$('stepBox').classList.remove('hidden');showStep()}
function showStep(){const steps=current.decisionSteps;if(stepIndex<steps.length){const st=steps[stepIndex];stepShownAt=Date.now();$('stepBox').innerHTML=`<small>STEP ${stepIndex+1} / ${steps.length}</small><h3>${st.prompt}</h3>`;const candidates=st.choices||[st.answer,'다시 확인'];candidates.forEach(x=>{const b=document.createElement('button');b.className='stepChoice';b.textContent=x;b.onclick=()=>{const ok=x===st.answer,stepElapsedSeconds=Math.max(0,Math.round((Date.now()-stepShownAt)/1000));logEvent('decision_step_answered',{payload:{attemptNo:attemptNo(),stepIndex:stepIndex+1,stepCorrect:ok,stepElapsedSeconds,familyId:current.familyId,sourceQuestionId:current.sourceQuestionId,variantType:current.variantType}});if(ok){b.classList.add('ok');setTimeout(()=>{stepIndex++;showStep()},250)}else{b.classList.add('no');const h=document.createElement('div');h.className='hint';h.textContent='교재 요약과 저자식 표식을 다시 확인하세요.';$('stepBox').appendChild(h)}};$('stepBox').appendChild(b)})}else showMicro()}
