async function next(){index++;if(index>=queue.length){await goHome('completed');return}render()}
async function retryOriginal(){if(!current)return;attemptNoByQuestion[current.id]=(attemptNoByQuestion[current.id]||1)+1;await logEvent('original_retry',{payload:{attemptNo:attemptNo()}});render()}
