function setupInk(){const sec=$('inkSection');if(!current.requiresInk){sec.classList.add('hidden');setChoiceGate('');return}sec.classList.remove('hidden');setChoiceGate('문장 표식을 완료하면 답 선택이 열립니다.');$('inkPrompt').textContent=current.inkPrompt||'문장에 직접 표시하세요.';renderTokenText();inkReady=false;$('inkDone').textContent='필기 완료 후 표식 감지';[...$('choices').children].forEach(b=>b.disabled=true);const saved=savedInk();actions=saved.actions||[];marks=saved.marks||[];canvas=$('inkCanvas');ctx=canvas.getContext('2d');if(resizeObs)resizeObs.disconnect();resizeObs=new ResizeObserver(()=>resizeCanvas());resizeObs.observe($('inkPaper'));resizeCanvas();selectTool('pen');$('penOnly').checked=penOnly;updatePenStatus('펜 대기');$('inkDetection').classList.add('hidden')}
