function redraw(){if(!ctx||!canvas)return;const r=canvas.getBoundingClientRect();ctx.clearRect(0,0,r.width,r.height);if(overlayMode!=='model'){for(const a of actions)drawAction(a);for(const m of marks)drawSemantic(m,false)}if(answerSubmitted&&overlayMode!=='mine')drawExpected()}
function normalizedPressure(p){if(!penProfile.pressureEnabled)return .5;const lo=Number(penProfile.pressureMin||0),hi=Math.max(lo+.01,Number(penProfile.pressureMax||1));return Math.max(0,Math.min(1,(Number(p||0)-lo)/(hi-lo)))}
function drawAction(a){if(!a.points?.length)return;const r=canvas.getBoundingClientRect(),cfg=toolCfg[a.tool]||toolCfg.pen;ctx.save();ctx.globalCompositeOperation=cfg.mode;ctx.globalAlpha=cfg.alpha;ctx.strokeStyle=a.tool==='highlighter'?'#f2c200':'#3425b7';ctx.lineCap='round';ctx.lineJoin='round';for(let i=1;i<a.points.length;i++){const p0=a.points[i-1],p1=a.points[i];ctx.beginPath();ctx.lineWidth=a.tool==='pen'?Math.max(1.5,cfg.width*(.55+normalizedPressure(p1.p))):cfg.width;ctx.moveTo(p0.x*r.width,p0.y*r.height);ctx.lineTo(p1.x*r.width,p1.y*r.height);ctx.stroke()}ctx.restore()}
function drawSemantic(m,model=false){const mt=tokenMetrics(),col=model?'#0a9958':'#3425b7';ctx.save();ctx.strokeStyle=col;ctx.lineWidth=model?2.5:3;ctx.setLineDash(model?[7,5]:[]);ctx.lineCap='round';if(m.type==='slash'){const p=gapPoint(m.gap);ctx.beginPath();ctx.moveTo(p.x-7,p.y+14);ctx.lineTo(p.x+7,p.y-14);ctx.stroke()}else if(m.type==='circle'){const z=mt[m.token];if(z){ctx.beginPath();ctx.ellipse(z.cx,z.cy,z.width/2+6,z.height/2+5,0,0,Math.PI*2);ctx.stroke()}}else if(m.type==='underline'){const a=mt[m.start],b=mt[m.end??m.start];if(a&&b){if(Math.abs(a.cy-b.cy)<a.height){ctx.beginPath();ctx.moveTo(a.left,a.bottom+5);ctx.lineTo(b.right,b.bottom+5);ctx.stroke()}else{for(let i=m.start;i<=m.end;i++){const z=mt[i];if(z){ctx.beginPath();ctx.moveTo(z.left,z.bottom+5);ctx.lineTo(z.right,z.bottom+5);ctx.stroke()}}}}}ctx.restore()}
function drawExpected(){const s=current.annotationSpec;if(!s)return;for(const g of s.expectedBreaks||[])drawSemantic({type:'slash',gap:g},true);for(const t of s.focusTargets||[])drawSemantic({type:'circle',token:t},true);for(const r of s.underlineRanges||[])drawSemantic({type:'underline',start:r[0],end:r[r.length-1]},true)}
function pointFromEvent(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height,p:e.pressure>0?e.pressure:.5,t:Date.now()-questionShownAt}}
function pixelPoint(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function effectiveTool(e){if((e.buttons&32)===32)return'eraser';if((e.buttons&2)===2)return'highlighter';return tool}
function down(e){if(!current?.requiresInk)return;if((penOnly||penProfile.palmGuard)&&e.pointerType==='touch')return;e.preventDefault();canvas.setPointerCapture?.(e.pointerId);const t=effectiveTool(e),p=pixelPoint(e);updatePenStatus(`${e.pointerType||'입력'} · 압력 ${(e.pressure||0).toFixed(2)}`);if(t==='slash'){marks.push({type:'slash',gap:nearestGap(p.x,p.y),source:'smart',t:Date.now()-questionShownAt});redraw();commitInk();return}if(t==='circle'){marks.push({type:'circle',token:nearestToken(p.x,p.y),source:'smart',t:Date.now()-questionShownAt});redraw();commitInk();return}if(t==='underline'){underlineStart=nearestToken(p.x,p.y);active={tool:'semantic-underline',points:[pointFromEvent(e)]};return}active={tool:t,points:[pointFromEvent(e)]}}
