function commitInk(){const __rcStart=performance.now();inkDB[current.id]={actions,marks,evaluation:lastAssessment};saveInk();window.JK_RC?.recordDuration('inkCommit',performance.now()-__rcStart,{questionId:current.id,strokeCount:actions.length})}
function selectTool(t){tool=t;document.querySelectorAll('.inkTool').forEach(b=>b.classList.toggle('selected',b.dataset.tool===t))}
function updatePenStatus(s){$('penStatus').textContent=s}
function geometry(a){const ps=a.points||[];if(ps.length<2)return null;let minx=1,miny=1,maxx=0,maxy=0,len=0;for(let i=0;i<ps.length;i++){const p=ps[i];minx=Math.min(minx,p.x);miny=Math.min(miny,p.y);maxx=Math.max(maxx,p.x);maxy=Math.max(maxy,p.y);if(i)len+=Math.hypot(p.x-ps[i-1].x,p.y-ps[i-1].y)}const first=ps[0],last=ps[ps.length-1];return{minx,miny,maxx,maxy,w:maxx-minx,h:maxy-miny,cx:(minx+maxx)/2,cy:(miny+maxy)/2,len,close:Math.hypot(first.x-last.x,first.y-last.y),dx:last.x-first.x,dy:last.y-first.y}}
