function unlockChoices(){inkReady=true;const d=detectedMarks();logEvent('mark_confirmed',{methodScore:null,payload:{attemptNo:attemptNo(),strokeCount:actions.length,markCount:d.length}});const slashes=d.filter(x=>x.type==='slash').length,focus=d.filter(x=>x.type!=='slash').length;[...$('choices').children].forEach(b=>b.disabled=false);setChoiceGate('');$('inkDone').textContent='표식 기록됨 · 답을 선택하세요';$('inkDetection').innerHTML=`<strong>표식 감지</strong><span>/ ${slashes}개 · 동그라미·밑줄 ${focus}개</span><small>정확한 위치 점수는 답을 선택한 뒤 공개됩니다.</small>`;$('inkDetection').classList.remove('hidden');commitInk()}
